/**
 * Natural frequencies of the OC4 platform, from the modal analysis already in
 * the repository (`src/tools/modal_analysis/modal_properties.txt`, generated by
 * `prepare_modal_properties.py`).
 *
 * Only the elastic modes are useful here: modes 8-12 sit at ~0.0005 Hz, which is
 * the numerical zero of the six rigid-body modes (surge, sway, heave, roll,
 * pitch, yaw) — there is nothing to see there.
 *
 * The dominant axis comes from the modal masses: `mass_x` for surge, `mass_y`
 * for sway, `mass_z` for heave.
 */
export interface NaturalMode {
    /** Mode number as reported by the solver. */
    id: number;
    freqHz: number;
    /** Axis the modal mass is concentrated on. */
    axis: 'x' | 'y' | 'z';
    /** Share of the total modal mass on that axis, in percent. */
    participation: number;
    label: string;
}

export const NATURAL_MODES: NaturalMode[] = [
    { id: 13, freqHz: 0.5102, axis: 'x', participation: 19.3, label: 'Surge' },
    { id: 14, freqHz: 0.5710, axis: 'y', participation: 15.2, label: 'Sway' },
    { id: 15, freqHz: 2.0455, axis: 'z', participation: 27.0, label: 'Heave' },
    { id: 16, freqHz: 2.5683, axis: 'y', participation: 23.9, label: 'Balanceo' },
    { id: 20, freqHz: 4.3766, axis: 'z', participation: 27.9, label: '2.º vertical' },
    { id: 27, freqHz: 10.892, axis: 'x', participation: 0.2, label: 'Local' },
];

/**
 * Frequencies the detector can actually resolve.
 *
 * The loop runs at ~10 fps, so the Nyquist limit is 5 Hz: the 4.4 Hz mode is at
 * the edge and the 10.9 Hz one is simply not observable from keypoints.
 */
export function observableModes(sampleRate: number): NaturalMode[] {
    const limit = sampleRate / 2;
    return NATURAL_MODES.filter((mode) => mode.freqHz < limit);
}
